const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage({ viewport: { width: 1366, height: 900 } });
  const detailUrl = 'http://127.0.0.1:8765/tuyen-dung/ke-toan-tong-hop-cong-ty-tnhh-thuc-pham-tadichi.html';
  await page.goto(detailUrl, { waitUntil: 'networkidle' });
  const detail = await page.evaluate(() => ({
    actionCard: !!document.querySelector('.job-detail-action-card'),
    keywords: document.querySelectorAll('.job-keyword-chip').length,
    report: !!Array.from(document.querySelectorAll('a')).find(a => a.textContent.includes('Báo tin sai') && a.href.startsWith('mailto:')),
    shareBox: !!document.querySelector('.job-detail-share-box'),
    sourceBox: !!document.querySelector('.job-detail-source-card'),
    deadlineExpired: !!document.querySelector('.job-detail-deadline-pill.is-expired'),
    heroColumns: getComputedStyle(document.querySelector('.job-detail-top')).gridTemplateColumns,
  }));
  await page.click('[data-job-copy-link]');
  await page.waitForTimeout(250);
  const feedback = await page.locator('[data-job-share-feedback]').first().textContent().catch(() => '');

  await page.goto('http://127.0.0.1:8765/tuyen-dung.html?hinh-thuc=full-time#job-list', { waitUntil: 'networkidle' });
  const employment = await page.$eval('#jobsFilterEmployment', el => el.value);
  await page.goto('http://127.0.0.1:8765/tuyen-dung.html?nganh=ke-toan-tong-hop#job-list', { waitUntil: 'networkidle' });
  const role = await page.$eval('#jobsFilterRole', el => el.value);
  await page.goto('http://127.0.0.1:8765/tuyen-dung.html?cach-lam-viec=onsite#job-list', { waitUntil: 'networkidle' });
  const workMode = await page.$eval('#jobsFilterWorkMode', el => el.value);
  await page.goto('http://127.0.0.1:8765/tuyen-dung.html?kinh-nghiem=2-nam#job-list', { waitUntil: 'networkidle' });
  const experience = await page.$eval('#jobsFilterExperience', el => el.value);
  await browser.close();
  console.log(JSON.stringify({ detail, feedback, filters: { employment, role, workMode, experience } }, null, 2));
})().catch(err => { console.error(err); process.exit(1); });
